const data = $input.first().json;
const now = new Date();

let mode = data.body.mode;
if (mode === "DANGER") {
    mode = "Danger";
} else {
    mode = "Safe";
}

// لو date جاي null أو فاضي، استخدم التاريخ الحالي بصيغة YYYY-MM-DD
const date = data.body.date
    ? String(data.body.date)
    : now.toISOString().slice(0, 10);

let hours, minutes, seconds;

// لو time جاي null أو فاضي، استخدم الوقت الحالي، وإلا قسّم الوقت القادم
if (data.body.time && typeof data.body.time === "string" && data.body.time.trim() !== "") {
    [hours, minutes, seconds] = data.body.time.split(":").map(Number);
} else {
    hours = now.getHours();
    minutes = now.getMinutes();
    seconds = now.getSeconds();
}

hours = Number.isFinite(hours) ? hours : now.getHours();
minutes = Number.isFinite(minutes) ? minutes : now.getMinutes();
seconds = Number.isFinite(seconds) ? seconds : now.getSeconds();

const period = hours >= 12 ? "PM" : "AM";
const hours12 = hours % 12 || 12;

const updatedTime =
    `${hours12}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")} ${period}`;

return [
    {
        json: {
            machine: data.body.machine,
            mode: mode,
            temperature: data.body.temperature,
            device_id: data.body.device_id,
            boot_id: data.body.boot_id,
            event_id: data.body.event_id,
            risk_score: data.body.risk_score,
            current: data.body.current,
            vibration: data.body.vibration,
            date: date,
            time: updatedTime
        }
    }
];

