const rawInput = $input.first().json;

// Access the JSON data
const data = rawInput.data?.[0] ?? rawInput;
const now = new Date();

// Format the date (fallback to current date if missing/null)
const date = data.date || now.toISOString().slice(0, 10);

// Format the time from 24-hour to 12-hour format (fallback to current time if missing/null)
let hours, minutes, seconds;
if (typeof data.time === "string" && data.time.trim() !== "") {
    [hours, minutes, seconds] = data.time.split(":").map(Number);
} else {
    hours = now.getHours();
    minutes = now.getMinutes();
    seconds = now.getSeconds();
}

hours = Number.isFinite(hours) ? hours : now.getHours();
minutes = Number.isFinite(minutes) ? minutes : now.getMinutes();
seconds = Number.isFinite(seconds) ? seconds : now.getSeconds();

const period = hours >= 12 ? "PM" : "AM";
const formattedHours = hours % 12 || 12;

const formattedTime =
    `${formattedHours}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")} ${period}`;

// Format the machine mode and status icon like the screenshot
const isDanger = String(data.mode || "").toUpperCase() === "DANGER";
const mode = isDanger ? "Danger" : "Safe";
const statusIcon = isDanger ? "🔴" : "🟢";

// Build the report
let message = `🏭 *Machine Health Report — NileFlow AI*\n`;
message += `═══════════════════════\n`;
message += `\n`;
message += `⚙️ *Machine Information*\n`;
message += `🔹 *Machine:* ${data.machine || "Unknown"}\n`;
message += `🆔 *Device ID:* ${data.device_id}\n`;
message += `🔄 *Boot ID:* ${data.boot_id}\n`;
message += `📌 *Event ID:* ${data.event_id}\n`;
message += `\n`;
message += `🚨 *Machine Status*\n`;
message += `${statusIcon} *Mode:* ${mode}\n`;
message += `📊 *Risk Score:* ${Number(data.risk_score).toFixed(2)}\n`;
message += `\n`;
message += `🌡️ *Sensor Readings*\n`;
message += `🌡️ *Temperature:* ${data.temperature} °C\n`;
message += `⚡ *Current:* ${data.current} A\n`;
message += `📳 *Vibration:* ${data.vibration}\n`;
message += `\n`;
message += `📅 *Event Date:* ${date}\n`;
message += `🕒 *Event Time:* ${formattedTime}\n`;
message += `═══════════════════════`;

return [
    {
        json: {
            message: message,
            machine: data.machine,
            mode: mode,
            date: date,
            time: formattedTime,
            phoneNumber: "201028086887"
        }
    }
];

